before:
public void testClose() throws IOException {
    shielded.close();
    verify(original, never()).close();
    assertThrows(IOException.class, () -> shielded.write('x'), "write(c)");
    original.write('y');
    assertEquals(1, original.getBuilder().length());
    assertEquals('y', original.toString().charAt(0));
}

after:
public void testClose() throws IOException {
    shielded.close();
    verify(original, never()).close();
    assertThrows(IOException.class, () -> shielded.write('x'), "write(c)");
    original.write('y');
    assertEquals(1, original.getBuilder().length());
    assertEquals('y', original.toString().charAt(0));
}

before:
public void testLastIndexOf_char() {
    assertEquals(NOT_FOUND, StringUtils.lastIndexOf(null, ' '));
    assertEquals(NOT_FOUND, StringUtils.lastIndexOf("", ' '));
    assertEquals(7, StringUtils.lastIndexOf("aabaabaa", 'a'));
    assertEquals(5, StringUtils.lastIndexOf("aabaabaa", 'b'));

    assertEquals(5, StringUtils.lastIndexOf(new StringBuilder("aabaabaa"), 'b'));
    char[] charArray = new char[9];
    charArray[0] = '[';
    charArray[1] = '&';
    charArray[7] = '{';
    charArray[3] = '.';
    charArray[4] = 'c';
    charArray[5] = '.';
    charArray[6] = '0';
    charArray[7] = 'r';
    charArray[8] = 'o';
    CharBuffer charBuffer = CharBuffer.wrap(charArray);
    assertEquals(NOT_FOUND, StringUtils.lastIndexOf (charBuffer, (-1738), 982));
}

after:
public void testLastIndexOf_char() {
    assertEquals(-1, StringUtils.lastIndexOf(null, ' '));
    assertEquals(-1, StringUtils.lastIndexOf("", ' '));
    assertEquals(7, StringUtils.lastIndexOf("aabaabaa", 'a'));
    assertEquals(5, StringUtils.lastIndexOf("aabaabaa", 'b'));

    assertEquals(5, StringUtils.lastIndexOf(new StringBuilder("aabaabaa"), 'b'));
}

